/**
 * Generates the small PDF fixtures used by the browser tests.
 *
 * Run: node test/fixtures/make-fixtures.js
 * Outputs are committed so tests need no generator at run time. `password.pdf` is derived from
 * `plain.pdf` with Ghostscript (the generator prints the command) because PDF encryption is not
 * worth re-implementing here.
 */
const fs = require("fs");
const path = require("path");

/**
 * Assembles a PDF from object bodies. Object numbers are 1-based list positions.
 *
 * @param {string[]} bodies - Object bodies without the `n 0 obj` / `endobj` wrapper
 * @returns {Buffer} PDF file bytes
 */
function assemble(bodies) {
	let out = "%PDF-1.4\n";
	const offsets = [];
	bodies.forEach((body, i) => {
		offsets.push(out.length);
		out += `${i + 1} 0 obj\n${body}\nendobj\n`;
	});
	const xref = out.length;
	out += `xref\n0 ${bodies.length + 1}\n0000000000 65535 f \n`;
	offsets.forEach((o) => {
		out += `${String(o).padStart(10, "0")} 00000 n \n`;
	});
	out += `trailer\n<< /Size ${bodies.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
	return Buffer.from(out, "latin1");
}

/**
 * Builds a page content stream object that draws one line of Helvetica text.
 *
 * @param {string} text - ASCII text without parentheses
 * @param {number} y - Baseline height in points
 * @returns {string} Stream object body
 */
function textStream(text, y) {
	const content = `BT /F1 24 Tf 72 ${y} Td (${text}) Tj ET`;
	return `<< /Length ${content.length} >>\nstream\n${content}\nendstream`;
}

const FONT = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";

/**
 * @param {number} pageCount - Number of pages
 * @param {(n: number) => string} lineFor - Text of the single line on page n (1-based)
 * @param {(n: number) => string} annotsFor - `/Annots [...]` entry text for page n, or ""
 * @param {string[]} extra - Extra objects appended after the page objects
 * @returns {Buffer} PDF bytes
 */
function build(pageCount, lineFor, annotsFor, extra) {
	const firstPage = 4;
	const kids = [];
	const bodies = ["<< /Type /Catalog /Pages 2 0 R >>", "", FONT];
	for (let n = 1; n <= pageCount; n++) {
		const pageObj = firstPage + (n - 1) * 2;
		kids.push(`${pageObj} 0 R`);
		bodies.push(
			`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R >> >> /Contents ${pageObj + 1} 0 R ${annotsFor(n)} >>`,
			textStream(lineFor(n), 700),
		);
	}
	bodies[1] = `<< /Type /Pages /Kids [${kids.join(" ")}] /Count ${pageCount} >>`;
	return assemble(bodies.concat(extra));
}

const dir = __dirname;

// plain.pdf: three pages, each with a unique marker word and a repeated word for search counts.
fs.writeFileSync(
	path.join(dir, "plain.pdf"),
	build(
		3,
		(n) => `Page ${n} alpha marker${n} alpha`,
		() => "",
		[],
	),
);

// links.pdf: page 1 holds an https link, a javascript: link and an internal link to page 3.
// Annotation objects start after the 2 objects per page (3 pages -> objects 10, 11, 12).
const rect = (y) => `/Rect [72 ${y} 300 ${y + 30}] /Border [0 0 0]`;
fs.writeFileSync(
	path.join(dir, "links.pdf"),
	build(
		3,
		(n) => `Links page ${n}`,
		(n) => (n === 1 ? "/Annots [10 0 R 11 0 R 12 0 R]" : ""),
		[
			`<< /Type /Annot /Subtype /Link ${rect(600)} /A << /S /URI /URI (https://example.com/safe) >> >>`,
			`<< /Type /Annot /Subtype /Link ${rect(500)} /A << /S /URI /URI (javascript:alert\\(1\\)) >> >>`,
			`<< /Type /Annot /Subtype /Link ${rect(400)} /Dest [8 0 R /Fit] >>`,
		],
	),
);

console.log(
	"For password.pdf run (password: secret):\n" +
		"gs -q -dNOPAUSE -dBATCH -sDEVICE=pdfwrite -sOwnerPassword=owner -sUserPassword=secret " +
		"-dEncryptionR=3 -dKeyLength=128 -sOutputFile=test/fixtures/password.pdf test/fixtures/plain.pdf",
);

// jpx-image.pdf is hand-assembled from a 200x100 JPEG 2000 gradient made with
//   magick -size 200x100 gradient:red-blue g.jp2
// embedded with /Filter /JPXDecode. It pins how the viewer behaves when an image decoder is
// unavailable (docs/decision-log.md); it is not regenerated by this script.
